#!/usr/bin/env bash
#
# Maps the localized golden screenshots generated by test/screenshot_test.dart
# (./screenshots/<lang>/<scene>-<deviceType>-<WxH>.png) into the per-language
# folder layout that `fastlane supply` (Google Play) and `fastlane deliver`
# (App Store) expect. Each store locale is filled from the matching language
# folder (e.g. de-DE <- screenshots/de). The generated folders are .gitignored
# and recreated on demand (e.g. in CI before an upload), so they are never
# committed.
#
# Usage: scripts/prepare_store_screenshots.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$ROOT/screenshots"

ANDROID_LOCALES="en-US de-DE fr-FR es-ES it-IT pl-PL"
IOS_LOCALES="en-US de-DE fr-FR es-ES it pl"

# Order in which the scenes appear in the store listing.
SCENES="device devices virtualshifting-settings customization trainer companion"

# Editor decks (store_screenshots/, exported by scripts/store_screenshots.sh)
# land in screenshots/store/<lang>/<slot>/NN-*.png. Where a locale has one for
# a slot, it replaces that slot's Flutter-drawn boards; otherwise the boards
# below are used.
EDITOR="$ROOT/screenshots/store"

# use_editor <lang> <slot> <dest dir> <suffix>: copies the editor deck for
# <slot> (PNG for Apple, JPEG for Play) into <dest dir> as
# NN_editor<suffix>.<ext>; fails if there is none.
use_editor() {
  local src="$EDITOR/$1/$2" f n
  compgen -G "$src/*.*" >/dev/null || return 1
  for f in "$src"/*.png "$src"/*.jpg; do
    [ -e "$f" ] || continue
    n="$(basename "$f" | cut -c1-2)"
    cp "$f" "$3/${n}_editor$4.${f##*.}"
  done
}

if [ ! -d "$SRC" ]; then
  echo "Source screenshots folder not found: $SRC" >&2
  exit 1
fi

# --- Google Play (supply) --------------------------------------------------
# phoneScreenshots  <- android phone (1320x2868)
# tenInchScreenshots <- android tablet (3840x2400)
for loc in $ANDROID_LOCALES; do
  lang="${loc%%-*}"          # de-DE -> de
  src="$SRC/$lang"
  # Android images live under the metadata path, which is in the private prop
  # submodule (prop/store_metadata/android/...); these image dirs are gitignored
  # in prop.
  phone="$ROOT/prop/store_metadata/android/$loc/images/phoneScreenshots"
  ten="$ROOT/prop/store_metadata/android/$loc/images/tenInchScreenshots"
  seven="$ROOT/prop/store_metadata/android/$loc/images/sevenInchScreenshots"
  rm -rf "$phone" "$ten" "$seven"
  mkdir -p "$phone" "$ten" "$seven"
  use_editor "$lang" android "$phone" "" || {
    i=1
    for scene in $SCENES; do
      cp "$src/${scene}-android-1320x2868.png" "$phone/$(printf '%02d' "$i")_${scene}.png"
      i=$((i + 1))
    done
  }
  use_editor "$lang" androidTablet10 "$ten" "" || {
    i=1
    for scene in $SCENES; do
      cp "$src/${scene}-androidTablet-3840x2400.png" "$ten/$(printf '%02d' "$i")_${scene}.png"
      i=$((i + 1))
    done
  }
  # 7" tablets only get the editor deck; without one Play keeps none.
  use_editor "$lang" androidTablet7 "$seven" "" || rmdir "$seven"
  # The feature graphic (scripts/graphics.mjs), uploaded by its own lane.
  rm -f "$ROOT/prop/store_metadata/android/$loc/images/featureGraphic."*
  fg="$EDITOR/$lang/featureGraphic/01.jpg"
  [ -f "$fg" ] && cp "$fg" "$ROOT/prop/store_metadata/android/$loc/images/featureGraphic.jpg"
done

# --- App Store (deliver) ---------------------------------------------------
# deliver detects the device class from the image resolution:
#   iPhone 6.5"  <- 1242x2688
#   iPad 12.9"   <- 2752x2064 (boards) or 2064x2752 (editor deck)
for loc in $IOS_LOCALES; do
  lang="${loc%%-*}"          # de-DE -> de, it -> it
  src="$SRC/$lang"
  d="$ROOT/ios/fastlane/screenshots/$loc"
  rm -rf "$d"
  mkdir -p "$d"
  use_editor "$lang" iphone65 "$d" "_iphone65" || {
    i=1
    for scene in $SCENES; do
      cp "$src/${scene}-iPhone-1242x2688.png" "$d/$(printf '%02d' "$i")_${scene}_iphone65.png"
      i=$((i + 1))
    done
  }
  use_editor "$lang" ipad129 "$d" "_ipad129" || {
    i=1
    for scene in $SCENES; do
      cp "$src/${scene}-iPad-2752x2064.png" "$d/$(printf '%02d' "$i")_${scene}_ipad129.png"
      i=$((i + 1))
    done
  }
done

# --- Mac App Store (deliver, platform osx) ---------------------------------
# The macOS listing mirrors the iOS texts (the upload_metadata_macos lane points
# deliver at the same metadata path). Screenshots use the desktop renders, which
# are 2560x1600 — a valid Mac screenshot size that deliver maps to APP_DESKTOP.
for loc in $IOS_LOCALES; do
  lang="${loc%%-*}"          # de-DE -> de, it -> it
  src="$SRC/$lang"
  d="$ROOT/ios/fastlane/screenshots_macos/$loc"
  rm -rf "$d"
  mkdir -p "$d"
  use_editor "$lang" desktop "$d" "_desktop" || {
    i=1
    for scene in $SCENES; do
      cp "$src/${scene}-desktop-2560x1600.png" "$d/$(printf '%02d' "$i")_${scene}_desktop.png"
      i=$((i + 1))
    done
  }
done

echo "Prepared store screenshots for Play Store (${ANDROID_LOCALES}), App Store (${IOS_LOCALES}) and Mac App Store (${IOS_LOCALES})."
